// Normalize the error payload produced by the Error Trigger so it can be
// written to the analytics table in a structured way.
const e = $input.first().json;
const rawError = e && e.error;
const errorMessage = typeof rawError === 'string'
  ? rawError
  : (rawError && typeof rawError === 'object'
      ? (rawError.message || JSON.stringify(rawError))
      : JSON.stringify(rawError || 'unknown error'));

return [{
  json: {
    workflow_id: (e && e.workflowId) || '',
    workflow_name: (e && e.workflow && e.workflow.name) || (e && e.workflowName) || '',
    last_node: (e && e.lastNodeExecuted) || '',
    execution_id: (e && e.executionId) || '',
    error_message: String(errorMessage).slice(0, 2000),
    timestamp: (e && e.timestamp) || new Date().toISOString()
  }
}];
